// Browser-side data engine for static hosting (e.g. Vercel): reads the files written by
// backend/precip/export_static.py and answers the same requests as the FastAPI endpoints, with the same
// validation messages and rounding. Parity with the real API is tested in staticData.test.ts against
// golden outputs generated by backend/tools/make_golden.py.
import { ApiError } from "./types";
import type { MapResp, PointResp, ProbMapResp, ProbMeta, ProbPointResp, RunMeta, RunSummary, SeriesPoint, Status, VariableId, Kind } from "./types";

let BASE = "data/";
/** Test hook / custom hosting: where the exported files live (must end with "/"). */
export function setDataBase(base: string): void { BASE = base; cache.clear(); indexP = null; }

const cache = new Map<string, Promise<unknown>>();
function memo<T>(key: string, load: () => Promise<T>): Promise<T> {
  let p = cache.get(key) as Promise<T> | undefined;
  if (!p) {
    p = load().catch((e) => { cache.delete(key); throw e; });
    cache.set(key, p);
  }
  return p;
}

async function getJson<T>(path: string, fresh = false): Promise<T> {
  let r: Response;
  try { r = await fetch(BASE + path, fresh ? { cache: "no-store" } : undefined); } catch { throw new ApiError(0, "Cannot load the forecast data files."); }
  if (!r.ok) throw new ApiError(r.status === 404 ? 503 : r.status, "Forecast data files are not available yet.");
  return r.json() as Promise<T>;
}
async function getBin(path: string): Promise<ArrayBuffer> {
  let r: Response;
  try { r = await fetch(BASE + path); } catch { throw new ApiError(0, "Cannot load the forecast data files."); }
  if (!r.ok) throw new ApiError(r.status, `Data file ${path} could not be loaded (${r.status}).`);
  return r.arrayBuffer();
}

// ---- index and metadata -------------------------------------------------------------------------
interface IndexRun { run_id: string; issue_time_utc: string; published_at_utc?: string | null; max_step_h?: number }
interface Index { generated_at_utc: string; scheduled_refresh: boolean; refresh_minutes: number | null; runs: IndexRun[]; probability: IndexRun[] }
type Encoding = { dtype: string; shape: number[]; scale: number };
type StaticRunMeta = Omit<RunMeta, "freshness" | "attribution"> & { lats: number[]; lons: number[]; encodings: Record<string, Encoding>; model: string;
  world?: { lats: number[]; lons: number[]; encodings: Record<string, Encoding>; spacing_deg: number };
  /** Detailed 0.5 deg world, one file per variable and step (runs/<id>/w50/<key>_<step index>.bin). Absent on snapshot builds. */
  world50?: { spacing_deg: number; n_lat: number; n_lon: number; lat0: number; lon0: number; encodings: Record<string, { dtype: string; scale: number; shape: number[] }> } };
type StaticProbMeta = Omit<ProbMeta, "freshness" | "attribution"> & { lats: number[]; lons: number[]; encodings: Record<string, Encoding>; scale: number;
  domain: RunMeta["domain"]; units: string };

// index.json must stay fresh (it announces new runs) but every map/place request needs it to find the run files.
// Re-downloading it for each click added a network round trip to every interaction; reuse it for 20 s instead.
// The status poll (every 45 s) passes force=true, so a new run is still noticed promptly.
let indexAt = 0, indexP: Promise<Index> | null = null;
const INDEX_TTL_MS = 20_000;
const getIndex = (force = false): Promise<Index> => {
  if (!force && indexP && Date.now() - indexAt < INDEX_TTL_MS) return indexP;
  indexAt = Date.now();
  const p = getJson<Index>("index.json", true);
  indexP = p;
  p.catch(() => { if (indexP === p) indexP = null; });
  return p;
};

const STALE_H = 18, STALE_PROB_H = 36;
function freshness(issueIso: string, staleH: number) {
  const age = (Date.now() - Date.parse(issueIso)) / 3_600_000;
  return { age_hours: Math.round(age * 10) / 10, stale: age > staleH, stale_after_hours: staleH };
}
const r1 = (x: number) => Math.round(x * 10) / 10 || 0;      // 0.1 precision, never -0
const r2 = (x: number) => Math.round(x * 100) / 100 || 0;
const pyList = (a: number[]) => `[${a.join(", ")}]`;          // matches Python's list formatting in API messages

async function resolveRun(runId: string): Promise<StaticRunMeta> {
  const index = await getIndex();
  if (!index.runs.length) throw new ApiError(503, "No processed forecast run is available yet.");
  const id = runId === "latest" ? index.runs[0].run_id : runId;
  if (!index.runs.some((r) => r.run_id === id)) throw new ApiError(404, `Run ${id} is not available. See /api/runs.`);
  return memo(`meta|${id}`, () => getJson<StaticRunMeta>(`runs/${id}/meta.json`));
}
async function resolveProb(runId: string): Promise<StaticProbMeta> {
  const index = await getIndex();
  if (!index.probability.length) throw new ApiError(503, "No ECMWF probability run is available yet (published for 00 and 12 UTC runs only).");
  const id = runId === "latest" ? index.probability[0].run_id : runId;
  if (!index.probability.some((r) => r.run_id === id)) throw new ApiError(404, `Probability run ${id} is not available. See /api/probability/runs.`);
  return memo(`pmeta|${id}`, () => getJson<StaticProbMeta>(`prob/${id}/meta.json`));
}

type Arr = Float32Array | Int16Array | Uint8Array | Uint16Array;
async function loadArray(kind: "runs" | "prob", runId: string, file: string, enc: Encoding): Promise<Arr> {
  return memo(`${kind}|${runId}|${file}`, async () => {
    const buf = await getBin(`${kind}/${runId}/${file}`);
    const a = enc.dtype === "<f4" ? new Float32Array(buf) : enc.dtype === "<i2" ? new Int16Array(buf)
      : enc.dtype === "<u2" ? new Uint16Array(buf) : new Uint8Array(buf);
    const expected = enc.shape.reduce((p, q) => p * q, 1);
    if (a.length !== expected) throw new ApiError(500, `Data file ${file} has ${a.length} values, expected ${expected}.`);
    return a;
  });
}
const runArr = (m: StaticRunMeta, file: string) => loadArray("runs", m.run_id, file, m.encodings[file]);

function grid(a: Arr, offset: number, H: number, W: number, f: (v: number) => number): number[][] {
  const out: number[][] = new Array(H);
  for (let y = 0; y < H; y++) {
    const row = new Array<number>(W);
    const base = offset + y * W;
    for (let x = 0; x < W; x++) row[x] = f(a[base + x]);
    out[y] = row;
  }
  return out;
}

// ---- status, runs, metadata ---------------------------------------------------------------------
export async function fetchStatus(): Promise<Status> {
  const idx = await getIndex(true);
  return {
    refreshing: false, last_attempt_utc: idx.generated_at_utc, last_result: "static_build", last_error: null,
    auto_refresh: idx.scheduled_refresh, latest_run: idx.runs[0]?.run_id ?? null, mode: "static",
    probability: { latest_run: idx.probability[0]?.run_id ?? null, last_result: "static_build", last_error: null },
  };
}

export async function fetchRuns(): Promise<{ runs: RunSummary[] }> {
  const idx = await getIndex();
  return { runs: idx.runs.map((r) => ({ run_id: r.run_id, issue_time_utc: r.issue_time_utc, model: "ECMWF IFS HRES (oper/fc)",
    max_step_h: r.max_step_h ?? 0, ...freshness(r.issue_time_utc, STALE_H) })) };
}

export async function fetchRun(): Promise<RunMeta> {
  const m = await resolveRun("latest");
  const { lats: _la, lons: _lo, encodings: _en, ...meta } = m;
  void _la; void _lo; void _en;
  let delay: number | null = null;
  if (m.published_at_utc) delay = Math.round(((Date.parse(m.published_at_utc) - Date.parse(m.issue_time_utc)) / 3_600_000) * 100) / 100;
  return { ...meta, availability_delay_h: delay, freshness: freshness(m.issue_time_utc, STALE_H),
    attribution: "Contains modified ECMWF Open Data (IFS), CC-BY-4.0." } as RunMeta;
}

// ---- maps ---------------------------------------------------------------------------------------
export async function fetchMap(runId: string, step: number, variable: VariableId, kind: Kind, hours = 24, scope: "india" | "world" = "india"): Promise<MapResp> {
  if (variable === "prob") throw new ApiError(422, "Use the probability endpoints for variable=prob.");
  const m = await resolveRun(runId);
  const steps = m.steps_h;
  if (!Number.isInteger(step) || step < 0 || step > 144) throw new ApiError(422, "Input should be between 0 and 144.");
  if (!steps.includes(step)) throw new ApiError(422, `step ${step} is not a forecast step of this run; valid: ${pyList(steps)}`);
  const i = steps.indexOf(step);
  if (scope === "world" && m.world50?.encodings) {
    try { return await fetchMap50(m, i, step, variable, kind, hours); }
    catch (e) { if (!(e instanceof ApiError) || e.status !== 404) throw e; /* files not deployed: use the 2 deg layer below */ }
  }
  // scope=world: the coarse 2 deg global overview files (runs/<id>/world/*), same rules, different grid.
  if (scope === "world" && !m.world) throw new ApiError(404, `Run ${m.run_id} has no global overview (processed before it was added).`);
  const g = scope === "world" ? m.world! : m;
  const runArr = (_m: StaticRunMeta, file: string) => scope === "world" ? loadArray("runs", m.run_id, "world/" + file, g.encodings[file]) : loadArray("runs", m.run_id, file, g.encodings[file]);
  const H = g.lats.length, W = g.lons.length;
  const out = { run_id: m.run_id, step_h: step, variable, valid_time_utc: m.valid_times_utc[i], lats: g.lats, lons: g.lons };

  if (variable === "precip") {
    if (kind === "window") {
      const start = step - hours;
      if (!steps.includes(start)) {
        throw new ApiError(422, `A ${hours} h window ending at +${step} h would start at +${start} h, which is not a forecast step of this run `
          + `(steps: ${steps[0]}..${steps[steps.length - 1]} h, every 3 h). Choose a later end time or a shorter window.`);
      }
      const cum = await runArr(m, "cum.bin");
      const a = i * H * W, b = steps.indexOf(start) * H * W;
      // difference of cumulative fields, floored at 0 for packing noise (same rule as the API)
      const values = grid(cum, 0, H, W, () => 0);
      for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) values[y][x] = r1(Math.max(cum[a + y * W + x] - cum[b + y * W + x], 0));
      return { ...out, kind, accumulation_hours: hours, units: "mm", values };
    }
    if (kind === "interval") {
      if (i === 0) throw new ApiError(422, "step 0 has no interval total; use kind=cumulative or step >= 3");
      const arr = await runArr(m, "interval.bin");
      return { ...out, kind, accumulation_hours: m.interval_durations_h[i - 1], units: "mm", values: grid(arr, (i - 1) * H * W, H, W, r1) };
    }
    const arr = await runArr(m, "cum.bin");
    return { ...out, kind, accumulation_hours: step, units: "mm", values: grid(arr, i * H * W, H, W, r1) };
  }

  const base = { ...out, kind: "instant" as const, accumulation_hours: 0 };
  if (variable === "temp") {
    const arr = await runArr(m, "temp.bin");
    return { ...base, units: "°C", values: grid(arr, i * H * W, H, W, (v) => v / g.encodings["temp.bin"].scale) };
  }
  if (variable === "cloud") {
    const arr = await runArr(m, "cloud.bin");
    return { ...base, units: "%", values: grid(arr, i * H * W, H, W, (v) => v) };
  }
  const [ua, va] = await Promise.all([runArr(m, "u.bin"), runArr(m, "v.bin")]);
  const sc = g.encodings["u.bin"].scale;
  const speed = grid(ua, i * H * W, H, W, () => 0);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const k = i * H * W + y * W + x;
    speed[y][x] = r1(Math.hypot(ua[k] / sc, va[k] / sc));
  }
  return { ...base, units: "m/s", values: speed,
    u: grid(ua, i * H * W, H, W, (v) => r1(v / sc)), v: grid(va, i * H * W, H, W, (v) => r1(v / sc)) };
}

// ---- detailed 0.5 deg world (per-step files) -------------------------------------------------------------
async function chunk50(m: StaticRunMeta, key: string, idx: number): Promise<Arr> {
  const enc = m.world50!.encodings[key];
  return memo(`w50|${m.run_id}|${key}|${idx}`, async () => {
    const buf = await getBin(`runs/${m.run_id}/w50/${key}_${idx}.bin`);
    const a = enc.dtype === "<u2" ? new Uint16Array(buf) : enc.dtype === "<i2" ? new Int16Array(buf) : new Uint8Array(buf);
    if (a.length !== enc.shape[0] * enc.shape[1]) throw new ApiError(500, `Data file ${key}_${idx} has ${a.length} values.`);
    return a;
  });
}

async function fetchMap50(m: StaticRunMeta, i: number, step: number, variable: VariableId, kind: Kind, hours: number): Promise<MapResp> {
  const w = m.world50!, H = w.n_lat, W = w.n_lon, steps = m.steps_h;
  const lats = Array.from({ length: H }, (_, k) => Math.round((w.lat0 - k * w.spacing_deg) * 1e4) / 1e4);
  const lons = Array.from({ length: W }, (_, k) => Math.round((w.lon0 + k * w.spacing_deg) * 1e4) / 1e4);
  const out = { run_id: m.run_id, step_h: step, variable, valid_time_utc: m.valid_times_utc[i], lats, lons };
  const sc = (key: string) => w.encodings[key].scale;
  const diff = (a: Arr, b: Arr, k: number) => grid(a, 0, H, W, () => 0).map((row, y) => row.map((_, x) => r1(Math.max(a[y * W + x] - b[y * W + x], 0) / k)));
  if (variable === "precip") {
    const cum = await chunk50(m, "cum", i);
    if (kind === "window") {
      const prev = await chunk50(m, "cum", steps.indexOf(step - hours));
      return { ...out, kind, accumulation_hours: hours, units: "mm", values: diff(cum, prev, sc("cum")) };
    }
    if (kind === "interval") {
      const prev = await chunk50(m, "cum", i - 1);
      return { ...out, kind, accumulation_hours: m.interval_durations_h[i - 1], units: "mm", values: diff(cum, prev, sc("cum")) };
    }
    return { ...out, kind, accumulation_hours: step, units: "mm", values: grid(cum, 0, H, W, (v) => r1(v / sc("cum"))) };
  }
  const base = { ...out, kind: "instant" as const, accumulation_hours: 0 };
  if (variable === "temp") return { ...base, units: "°C", values: grid(await chunk50(m, "temp", i), 0, H, W, (v) => r1(v / sc("temp"))) };
  if (variable === "cloud") return { ...base, units: "%", values: grid(await chunk50(m, "cloud", i), 0, H, W, (v) => v) };
  const [ua, va] = await Promise.all([chunk50(m, "u", i), chunk50(m, "v", i)]);
  const k = sc("u");
  const speed = grid(ua, 0, H, W, () => 0);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) speed[y][x] = r1(Math.hypot(ua[y * W + x] / k, va[y * W + x] / k));
  return { ...base, units: "m/s", values: speed, u: grid(ua, 0, H, W, (v) => r1(v / k)), v: grid(va, 0, H, W, (v) => r1(v / k)) };
}

// ---- place series -------------------------------------------------------------------------------
function nearest(arr: number[], v: number): number {
  let best = 0;
  for (let i = 1; i < arr.length; i++) if (Math.abs(arr[i] - v) < Math.abs(arr[best] - v)) best = i;
  return best;
}
function checkDomain(d: RunMeta["domain"], lat: number, lon: number): void {
  const ok = Number.isFinite(lat) && Number.isFinite(lon) && lat >= d.lat_min && lat <= d.lat_max && lon >= d.lon_min && lon <= d.lon_max;
  if (!ok) throw new ApiError(422, `Location is outside the supported domain (${d.lat_min.toFixed(1)}–${d.lat_max.toFixed(1)}°N, ${d.lon_min.toFixed(1)}–${d.lon_max.toFixed(1)}°E).`);
}
const windDir = (u: number, v: number) => (((270 - (Math.atan2(v, u) * 180) / Math.PI) % 360) + 360) % 360;

export async function fetchPoint(runId: string, lat: number, lon: number, opts?: { light?: boolean }): Promise<PointResp> {
  const m = await resolveRun(runId);
  checkDomain(m.domain, lat, lon);
  const iy = nearest(m.lats, lat), ix = nearest(m.lons, lon);
  const H = m.lats.length, W = m.lons.length;
  const have = "temp.bin" in m.encodings && !opts?.light;
  const [cum, itv, temp, cloud, ua, va] = await Promise.all([
    runArr(m, "cum.bin"), runArr(m, "interval.bin"),
    have ? runArr(m, "temp.bin") : null, have ? runArr(m, "cloud.bin") : null,
    have ? runArr(m, "u.bin") : null, have ? runArr(m, "v.bin") : null,
  ]);
  const cell = iy * W + ix;
  const series: SeriesPoint[] = m.steps_h.map((s, i) => {
    const row: SeriesPoint = {
      step_h: s, valid_time_utc: m.valid_times_utc[i], cumulative_mm: r2(cum[i * H * W + cell]),
      interval_mm: i === 0 ? null : r2(itv[(i - 1) * H * W + cell]), interval_hours: i === 0 ? null : m.interval_durations_h[i - 1],
    };
    if (have && temp && cloud && ua && va) {
      const k = i * H * W + cell, sc = m.encodings["u.bin"].scale;
      const u = ua[k] / sc, v = va[k] / sc;
      row.temp_c = temp[k] / m.encodings["temp.bin"].scale; row.cloud_pct = cloud[k];
      row.wind_speed_ms = r1(Math.hypot(u, v)); row.wind_from_deg = Math.round(windDir(u, v)) % 360;
    }
    return row;
  });
  return { run_id: m.run_id, requested: { lat, lon }, grid_point: { lat: m.lats[iy], lon: m.lons[ix] },
    method: "Nearest grid point at 0.25° (~28 km); no interpolation. Represents a grid-cell value, not a point measurement.",
    units: "mm", series };
}

// ---- ECMWF ENS probabilities --------------------------------------------------------------------
export async function fetchProbMeta(): Promise<ProbMeta> {
  const m = await resolveProb("latest");
  const { lats: _la, lons: _lo, encodings: _en, ...meta } = m;
  void _la; void _lo; void _en;
  return { ...meta, freshness: freshness(m.issue_time_utc, STALE_PROB_H),
    attribution: "Contains modified ECMWF Open Data (IFS ENS probabilities), CC-BY-4.0." } as ProbMeta;
}

export async function fetchProbMap(runId: string, windowEnd: number, threshold: number): Promise<ProbMapResp> {
  const m = await resolveProb(runId);
  const ends = m.windows.map((w) => w.end_h);
  if (!ends.includes(windowEnd)) throw new ApiError(422, `window_end ${windowEnd} is not an available 24 h window end; valid: ${pyList(ends)}`);
  if (!m.thresholds_mm.includes(threshold)) throw new ApiError(422, `threshold ${threshold} mm is not available; valid: ${pyList(m.thresholds_mm)}`);
  const wi = ends.indexOf(windowEnd), ti = m.thresholds_mm.indexOf(threshold);
  const H = m.lats.length, W = m.lons.length, T = m.thresholds_mm.length;
  const arr = await loadArray("prob", m.run_id, "prob.bin", m.encodings["prob.bin"]);
  const w = m.windows[wi];
  return { run_id: m.run_id, variable: "prob", kind: "probability", units: "%", threshold_mm: threshold, window: w,
    issue_time_utc: m.issue_time_utc, valid_time_utc: w.end_utc, accumulation_hours: 24, lats: m.lats, lons: m.lons,
    values: grid(arr, (wi * T + ti) * H * W, H, W, (v) => Math.floor(v / m.scale + 0.5)) };
}

export async function fetchProbPoint(runId: string, lat: number, lon: number): Promise<ProbPointResp> {
  const m = await resolveProb(runId);
  checkDomain(m.domain, lat, lon);
  const iy = nearest(m.lats, lat), ix = nearest(m.lons, lon);
  const H = m.lats.length, W = m.lons.length, T = m.thresholds_mm.length;
  const arr = await loadArray("prob", m.run_id, "prob.bin", m.encodings["prob.bin"]);
  return { run_id: m.run_id, issue_time_utc: m.issue_time_utc, requested: { lat, lon }, grid_point: { lat: m.lats[iy], lon: m.lons[ix] },
    method: "Nearest 0.25° grid point; no interpolation.", units: "%", thresholds_mm: m.thresholds_mm,
    windows: m.windows.map((w, wi) => ({ ...w, probability_pct: m.thresholds_mm.map((_, ti) => Math.floor(arr[((wi * T + ti) * H + iy) * W + ix] / m.scale + 0.5)) })),
    semantics: (m as unknown as { semantics: string }).semantics };
}
